<?php if($accepted&&$paymentId===null):?><div class="fm2-otiz-v2-lifecycle"><button class="shlz-button shlz-button--danger" type="button" data-v2-lifecycle-open="cancel">Отменить расчёт</button><button class="shlz-button shlz-button--secondary" type="button" data-v2-lifecycle-open="replace">Заменить расчёт</button></div><?php foreach(['cancel'=>['Отменить расчёт?','Причина отмены','Подтвердить отмену'], 'replace'=>['Заменить расчёт?','Причина замены','Подтвердить замену']]as$kind=>[$title,$reasonLabel,$confirm]):?><dialog class="shlz-modal" data-v2-lifecycle-dialog="<?=$kind?>"><div class="shlz-modal__surface"><h2><?=$title?></h2><p data-confirm-summary>#<?=$id?> · <?=$date((string)$calculation['reportDate'])?> · <?=count($calculation['objects'])?> объекта · <?=$rub((int)$calculation['remainingPayableCents'])?></p><form method="post" action="/pilot/otiz/calculations/<?=$id?>/<?=$kind?>"><input type="hidden" name="_csrf" value="<?=Html::encode($csrf)?>"><input type="hidden" name="operationId" value="<?=ViewSupport::uuid()?>"><input type="hidden" name="expectedRevision" value="<?=$rev?>"><?php if($kind==='replace'):?><input type="hidden" name="reportDate" value="<?=Html::encode($calculation['reportDate'])?>"><?php endif?><label><?=$reasonLabel?><input class="shlz-input" name="reason" required></label><button class="shlz-button <?=$kind==='cancel'?'shlz-button--danger':'shlz-button--primary'?>"><?=$confirm?></button></form><button class="shlz-button shlz-button--secondary" type="button" data-v2-lifecycle-cancel>Отмена</button></div></dialog><?php endforeach?><button class="shlz-button shlz-button--primary fm2-otiz-v2-pay" type="button" data-v2-payment-open>Отметить выплату</button><dialog class="shlz-modal" data-v2-payment-dialog><div class="shlz-modal__surface"><h2>Подтвердите фактическую выплату</h2><form method="post" action="/pilot/otiz/calculations/<?=$id?>/payments" data-v2-payment-form><input type="hidden" name="_csrf" value="<?=Html::encode($csrf)?>"><input type="hidden" name="operationId" value="<?=ViewSupport::uuid()?>"><input type="hidden" name="expectedRevision" value="<?=$rev?>"><p data-confirm-summary><strong>#<?=$id?> · <?=$date((string)$calculation['reportDate'])?> · <?=count($calculation['objects'])?> объекта · <?=$rub((int)$calculation['remainingPayableCents'])?></strong><br>FMonitor только фиксирует выплату, выполненную вне FMonitor, и не переводит деньги.</p><label>Дата фактической выплаты<input type="date" name="paymentDate"></label><footer class="shlz-modal__footer"><button class="shlz-button shlz-button--secondary" type="button" data-v2-payment-cancel>Отмена</button><button class="shlz-button shlz-button--primary">Подтвердить выплату</button></footer></form></div></dialog><?php endif?>
