<?php if(($calculation['history']??[])!==[]):?><section class="fm2-otiz-surface" data-calculation-history><h2>История расчёта</h2><ul><?php foreach($calculation['history']as$event):$type=(string)($event['type']??'');$label=match($type){'draft_created'=>'Черновик создан','paid'=>'Выплата отмечена','payment_reversed'=>'Ошибочная отметка отменена','accepted'=>'Расчёт утверждён','cancelled'=>'Расчёт отменён','replacement_draft_created'=>'Замена подготовлена','deduction_saved'=>'Удержание сохранено','deduction_removed'=>'Удержание удалено','decision_saved'=>'Решение по выплате сохранено',default=>'Событие '.$type};$reason=(string)($event['payload']['reason']??$event['payment']['reversal_reason']??'');$at=(string)($event['createdAt']??'');$actor=(int)($event['actorId']??0);?><li><strong><?=Html::encode($label)?></strong><?php if($at!==''):?> · <time datetime="<?=Html::encode($at)?>"><?=Html::encode($at)?></time><?php endif?><?php if($actor>0):?> · пользователь #<?=$actor?><?php endif?><?=$reason!==''?' · '.Html::encode($reason):''?></li><?php endforeach?></ul></section><?php endif?></main><?php ViewSupport::end($this);?>
